    'Sau khoảng giá trị này được thực thi. Điều này đưa ra sự chậm trễ trong việc kích hoạt thông gió trong trường hợp nhiệt độ tăng hoặc sự chậm trễ trong quá trình kích hoạt tự nhiên trong trường hợp nhiệt độ giảm.'
