    EnTextos.textMensaMinimoTiempoOff,
    'Thời gian tối thiểu mà quạt có thể tắt. Nếu thời gian tắt máy ngắn hơn thông số này, quạt sẽ không tắt, nó sẽ tiếp tục bật. Thông số này phải lớn hơn thời gian được chỉ ra.Thời gian dự đoán của đầu vào (tăng / giảm m3h), trong “Menu - Cấu hình - Áp suất âm - Nâng cao”'
