    'Chế độ lũy tiến: Trong chế độ này, bạn bật từng giai đoạn một. Chế độ quay: ở chế độ này bạn bật hết màn này đến màn khác nhưng thay đổi màn đầu tiên được kết nối. Giai đoạn đầu tiên sẽ thay đổi mỗi khi tắt chế độ làm mát.'
