    EnTextos.textMensOrigenPienso,
    'Chúng tôi cho biết tổng thức ăn đã tiêu thụ bắt nguồn từ đâu. Bộ đếm thời gian, Thức ăn tiêu thụ được thực hiện bởi bộ đếm thời gian. Các silo, thức ăn được tiêu thụ là thứ được tiêu thụ trong tất cả các silo được kết nối. Silo (1,2,3), chúng tôi cho biết silo nào là silo sẽ tính lượng thức ăn đã tiêu thụ.'
